### 实现原理

Promise 版 AJAX 请求函数的核心是**用 Promise 对象封装 XMLHttpRequest（XHR）的异步操作**，将请求的成功 / 失败状态与 Promise 的 resolve/reject 机制关联，从而实现更优雅的异步处理流程。

其工作流程可分为三个阶段：



1.  初始化 Promise 并配置 XHR 参数

2.  监听 XHR 状态变化，处理成功 / 失败场景

3.  解析响应数据并通过 Promise 传递结果

### 完整实现代码



```
/\*\*

&#x20;\* Promise版AJAX请求函数

&#x20;\* @param {Object} options - 请求配置参数

&#x20;\* @param {string} options.url - 请求地址（必填）

&#x20;\* @param {string} \[options.method='GET'] - 请求方法，默认为GET

&#x20;\* @param {Object} \[options.data=null] - 请求数据

&#x20;\* @param {Object} \[options.headers={}] - 请求头

&#x20;\* @param {number} \[options.timeout=0] - 超时时间（0表示无超时）

&#x20;\* @param {string} \[options.responseType=''] - 响应数据类型

&#x20;\* @returns {Promise} 返回Promise对象

&#x20;\*/

function ajax(options) {

&#x20; // 返回Promise实例，在 executor 函数中执行AJAX操作

&#x20; return new Promise((resolve, reject) => {

&#x20;   // 1. 参数处理与默认值设置

&#x20;   const {

&#x20;     url,

&#x20;     method = 'GET',

&#x20;     data = null,

&#x20;     headers = {},

&#x20;     timeout = 0,

&#x20;     responseType = ''

&#x20;   } = options;

&#x20;   // 校验必填参数

&#x20;   if (!url) {

&#x20;     reject(new Error('请求地址url为必填参数'));

&#x20;     return;

&#x20;   }

&#x20;   // 2. 初始化XMLHttpRequest对象

&#x20;   const xhr = new XMLHttpRequest();

&#x20;   // 3. 配置请求（方法、地址、是否异步）

&#x20;   // 第三个参数true表示异步请求，这是AJAX的核心特性

&#x20;   xhr.open(method.toUpperCase(), url, true);

&#x20;   // 4. 设置请求头

&#x20;   // 默认设置Content-Type，根据数据类型自动适配

&#x20;   if (data && !headers\['Content-Type']) {

&#x20;     if (typeof data === 'object' && !(data instanceof FormData)) {

&#x20;       // JSON数据设置为application/json

&#x20;       xhr.setRequestHeader('Content-Type', 'application/json');

&#x20;     } else {

&#x20;       // 表单数据或其他类型设置为表单编码

&#x20;       xhr.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded');

&#x20;     }

&#x20;   }

&#x20;   // 设置用户自定义请求头

&#x20;   Object.keys(headers).forEach(key => {

&#x20;     xhr.setRequestHeader(key, headers\[key]);

&#x20;   });

&#x20;   // 5. 设置响应数据类型（可选）

&#x20;   // 如设置为'json'可自动解析JSON响应，无需手动JSON.parse()

&#x20;   xhr.responseType = responseType;

&#x20;   // 6. 设置超时时间

&#x20;   if (timeout > 0) {

&#x20;     xhr.timeout = timeout;

&#x20;   }

&#x20;   // 7. 监听请求状态变化

&#x20;   xhr.onreadystatechange = function() {

&#x20;     // readyState为4表示请求已完成

&#x20;     if (xhr.readyState === 4) {

&#x20;       // HTTP状态码在200-299之间表示请求成功

&#x20;       if (xhr.status >= 200 && xhr.status < 300) {

&#x20;         // 准备响应结果对象

&#x20;         const response = {

&#x20;           data: xhr.responseType === 'json' ? xhr.response : xhr.responseText,

&#x20;           status: xhr.status,

&#x20;           statusText: xhr.statusText,

&#x20;           headers: xhr.getAllResponseHeaders()

&#x20;         };

&#x20;         resolve(response);

&#x20;       } else {

&#x20;         // 非成功状态码，返回错误信息

&#x20;         reject(new Error(\`请求失败: \${xhr.status} \${xhr.statusText}\`));

&#x20;       }

&#x20;     }

&#x20;   };

&#x20;   // 8. 监听网络错误

&#x20;   xhr.onerror = function() {

&#x20;     reject(new Error('网络错误，无法完成请求'));

&#x20;   };

&#x20;   // 9. 监听超时错误

&#x20;   xhr.ontimeout = function() {

&#x20;     reject(new Error(\`请求超时（\${timeout}ms）\`));

&#x20;   };

&#x20;   // 10. 处理请求数据并发送请求

&#x20;   let requestData = null;

&#x20;   if (data) {

&#x20;     const methodType = method.toUpperCase();

&#x20;     // GET/HEAD请求的数据通过URL参数传递，不设置请求体

&#x20;     if (methodType === 'GET' || methodType === 'HEAD') {

&#x20;       // 无需处理请求体，数据已通过URL参数传递

&#x20;     } else if (data instanceof FormData) {

&#x20;       // FormData类型直接作为请求体

&#x20;       requestData = data;

&#x20;     } else if (typeof data === 'object') {

&#x20;       // JSON对象转换为JSON字符串

&#x20;       requestData = JSON.stringify(data);

&#x20;     } else {

&#x20;       // 其他类型（如查询字符串）直接使用

&#x20;       requestData = data;

&#x20;     }

&#x20;   }

&#x20;   // 发送请求（GET请求时requestData为null）

&#x20;   xhr.send(requestData);

&#x20; });

}
```

### 关键技术点解析



1.  **参数处理机制**

*   使用对象解构赋值设置默认参数，提高灵活性

*   对必填参数（url）进行校验，提前抛出错误

*   自动处理 Content-Type，减少用户配置成本

1.  **Promise 与 XHR 的关联**

*   在 Promise 的 executor 函数中执行 XHR 操作，将异步操作纳入 Promise 管理

*   成功场景（2xx 状态码）调用`resolve`传递响应数据

*   失败场景（网络错误、超时、非 2xx 状态码）调用`reject`传递错误信息

1.  **响应数据处理**

*   通过`xhr.responseType`设置自动解析类型（如 'json'）

*   封装完整响应信息（数据、状态码、响应头），方便后续处理

*   兼容不同数据类型（FormData、JSON、普通文本）

1.  **错误处理机制**

*   网络错误：通过`xhr.onerror`捕获

*   超时错误：通过`xhr.ontimeout`捕获

*   HTTP 错误状态：通过状态码判断（非 2xx 范围）

### 扩展功能实现

基于基础版可以扩展以下实用功能：



```
// 扩展：便捷的GET请求方法

ajax.get = function(url, options = {}) {

&#x20; return ajax({ ...options, url, method: 'GET' });

};

// 扩展：便捷的POST请求方法

ajax.post = function(url, data, options = {}) {

&#x20; return ajax({ ...options, url, method: 'POST', data });

};

// 扩展：处理查询参数拼接

function serializeParams(data) {

&#x20; if (!data || typeof data !== 'object') return '';

&#x20; const params = \[];

&#x20; for (const key in data) {

&#x20;   if (data.hasOwnProperty(key)) {

&#x20;     params.push(\`\${encodeURIComponent(key)}=\${encodeURIComponent(data\[key])}\`);

&#x20;   }

&#x20; }

&#x20; return params.length ? \`?\${params.join('&')}\` : '';

}

// 增强版ajax函数（增加查询参数自动拼接）

function advancedAjax(options) {

&#x20; let { url, data, method = 'GET' } = options;

&#x20; // GET请求自动拼接查询参数

&#x20; if (method.toUpperCase() === 'GET' && data) {

&#x20;   url += serializeParams(data);

&#x20;   options.data = null; // 清除data，避免重复发送

&#x20; }

&#x20; return ajax({ ...options, url });

}
```

### 使用示例



```
// 基础使用示例

ajax({

&#x20; url: 'https://api.example.com/data',

&#x20; method: 'POST',

&#x20; data: { username: 'test', password: '123' },

&#x20; timeout: 5000

})

.then(response => {

&#x20; console.log('请求成功:', response.data);

&#x20; return response.data; // 可以继续链式调用

})

.catch(error => {

&#x20; console.error('请求失败:', error.message);

});

// 使用便捷方法

ajax.get('https://api.example.com/users', {

&#x20; data: { page: 1, limit: 10 }

})

.then(res => console.log('用户列表:', res.data));

// 结合async/await使用（更优雅的写法）

async function fetchData() {

&#x20; try {

&#x20;   const response = await ajax.post(

&#x20;     'https://api.example.com/login',

&#x20;     { username: 'admin', password: 'admin123' }

&#x20;   );

&#x20;   console.log('登录成功:', response.data.token);

&#x20;   return response.data.token;

&#x20; } catch (error) {

&#x20;   console.error('登录失败:', error.message);

&#x20; }

}

fetchData();
```

### 与 fetch API 的对比



| 特性   | 自定义 Promise AJAX | 原生 fetch API                |
| ---- | ---------------- | --------------------------- |
| 兼容性  | 需 IE8+（需 XHR 支持） | 现代浏览器（IE 不支持）               |
| 超时处理 | 原生支持 xhr.timeout | 需要额外封装 Promise.race         |
| 错误处理 | 自动识别 HTTP 错误状态   | 仅网络错误会 reject，HTTP 错误需手动判断  |
| 默认行为 | 不发送 cookie       | 需要设置 credentials: 'include' |
| 响应处理 | 可自动解析 JSON       | 需要手动调用 response.json ()     |

自定义 Promise 版 AJAX 在兼容性和错误处理上更灵活，适合需要兼容旧环境的场景；而 fetch API 是浏览器原生支持的 Promise 风格 API，更符合现代前端开发趋势。

### 总结

实现 Promise 版 AJAX 的核心是理解**Promise 的状态管理**与**XHR 的异步特性**的结合方式。通过封装，我们将复杂的 XHR 操作抽象为简单的 Promise 接口，既保留了 AJAX 的功能完整性，又获得了 Promise 带来的链式调用和异步流程控制能力，为处理复杂异步场景（如请求依赖、并发请求）提供了便利。
